Here is the root cause:
The bug was caused by an incorrect handling of the test bits depth when the bits per color (BPC) is unknown. Specifically, the value of `DP_TEST_BIT_DEPTH_8` was being left-shifted again, leading to an overflow that affected other bits in the `DP_CONFIGURATION_CTRL` register. This occurred because the function `dp_link_get_test_bits_depth` was returning a value that was not properly adjusted for the unknown case, resulting in unintended modifications to the configuration register.

Here is the patch:

 static void dp_ctrl_config_ctrl(struct dp_ctrl_private *ctrl)
 {
 	u32 config = 0, tbd;
 	const u8 *dpcd = ctrl->panel->dpcd;

 	/* Default-> LSCLK DIV: 1/4 LCLK  */
 	config |= (2 << DP_CONFIGURATION_CTRL_LSCLK_DIV_SHIFT);

 	/* Scrambler reset enable */
 	if (drm_dp_alternate_scrambler_reset_cap(dpcd))
 		config |= DP_CONFIGURATION_CTRL_ASSR;

 	tbd = dp_link_get_test_bits_depth(ctrl->link,
 			ctrl->panel->dp_mode.bpp);

-	if (tbd == DP_TEST_BIT_DEPTH_UNKNOWN) {
-		pr_debug("BIT_DEPTH not set. Configure default\n");
-		tbd = DP_TEST_BIT_DEPTH_8;
-	}
-
 	config |= tbd << DP_CONFIGURATION_CTRL_BPC_SHIFT;

 	/* Num of Lanes */
 	config |= ((ctrl->link->link_params.num_lanes - 1)
 			<< DP_CONFIGURATION_CTRL_NUM_OF_LANES_SHIFT);

 	if (drm_dp_enhanced_frame_cap(dpcd))
 		config |= DP_CONFIGURATION_CTRL_ENHANCED_FRAMING;

 	config |= DP_CONFIGURATION_CTRL_P_INTERLACED; /* progressive video */

 	/* sync clock & static Mvid */
 	config |= DP_CONFIGURATION_CTRL_STATIC_DYNAMIC_CN;
 	config |= DP_CONFIGURATION_CTRL_SYNC_ASYNC_CLK;

 	if (ctrl->panel->psr_cap.version)
 		config |= DP_CONFIGURATION_CTRL_SEND_VSC;

 	dp_catalog_ctrl_config_ctrl(ctrl->catalog, config);
 }



